import sys
from itertools import combinations

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:]))

    total_sum = sum(a)
    found = False

    for k in range(1, n):
        for comb in combinations(range(n), k):
            if sum(a[i] for i in comb) != total_sum - sum(a[i] for i in comb):
                found = True
                print(k)
                print(' '.join(map(str, [x + 1 for x in comb])))
                break
        if found:
            break

    if not found:
        print(-1)

if __name__ == "__main__":
    main()
